func diffFilePath(f DiffFile) string {
	if f.NewPath != "" {
		return f.NewPath
	}
	return f.OldPath
}

func diffLineClass(t string) string {
	switch t {
	case "add":
		return "diff-add"
	case "del":
		return "diff-del"
	default:
		return ""
	}
}

func diffPrefix(t string) string {
	if t == "add" {
		return "+"
	}
	if t == "del" {
		return "-"
	}
	return ""
}

func lineNum(line DiffLine) int {
	if line.NewLine > 0 {
		return line.NewLine
	}
	return line.OldLine
}

func lineNumStr(n int) string {
	if n <= 0 {
		return ""
	}
	return strconv.Itoa(n)
}

